'use strict';
/* V13 Kitap Arkadaşım – Kitap Sınavları. Öğrenci cevap anahtarları istemciye gönderilmez. */
const BookExams=(()=>{
const $=id=>document.getElementById(id);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='student',exam=null,bookList=[],isAdmin=false;
let examClock=null,saveCurrentAnswer=null,submitting=false;
function stopExamClock(){if(examClock!==null){clearInterval(examClock);examClock=null}}
function formatDuration(seconds){seconds=Math.max(0,Math.floor(Number(seconds)||0));return `${Math.floor(seconds/60)} dk ${String(seconds%60).padStart(2,'0')} sn`}
function timerHTML(){return exam?.deadlineAt?'<p class="be-note" style="font-weight:750;font-size:1.05rem" id="be-timer" role="timer">⏱️ Kalan süre hesaplanıyor…</p>':'<p class="be-note">⏱️ Süresiz sınav · Tamamlama süreniz kaydedilecek.</p>'}
function runClock(){stopExamClock();if(!exam?.deadlineAt)return;const update=()=>{if(!exam||!exam.deadlineAt){stopExamClock();return}const left=Math.max(0,Math.ceil((exam.deadlineAt-Date.now())/1000)),node=$('be-timer');if(node){node.textContent=`⏱️ Kalan süre: ${formatDuration(left)}`;node.style.color=left<=30?'#b91c1c':''}if(left===0){stopExamClock();if(typeof saveCurrentAnswer==='function')saveCurrentAnswer();submitExam(true)}};update();if(exam&&Date.now()<exam.deadlineAt)examClock=setInterval(update,500)}
async function submitExam(forced=false){if(!exam||submitting)return;if(!forced&&answers.some(v=>v===null)){status('Tüm soruları yanıtlayın.');return}submitting=true;stopExamClock();const button=$('be-submit');if(button)button.disabled=true;status(forced?'Süre doldu. Cevaplarınız gönderiliyor…':'Sınav kaydediliyor…');try{const r=await api('submit',{attemptId:exam.attemptId,answers});app.innerHTML=top('SINAV TAMAMLANDI',r.timedOut?'Süreniz doldu':'Tebrikler!',r.timedOut?'Sınav süresi sona erdi.':'Kitap sınavını bitirdin.')+`<section class="be-card be-narrow be-result"><h2>${r.score} / 100 puan</h2><p>${r.total} sorunun ${r.correct} tanesi doğru.</p><p><strong>⏱️ Sınav süresi: ${formatDuration(r.elapsedSeconds)}</strong></p>${r.lateBeyondGrace?'<p class="be-note">Süre aşımı nedeniyle geç gönderilen cevaplar puanlanmadı.</p>':''}<p>Cevap anahtarı sınav güvenliği için gösterilmez.</p><button class="v12-btn v12-btn-accent" id="be-list-back">Kitaplara dön</button></section>`;$('be-list-back').onclick=books;exam=null;answers=[];saveCurrentAnswer=null}catch(e){status(e.message+' Bağlantıyı kontrol edip tekrar deneyin.');if(button?.isConnected)button.disabled=false;if(exam?.deadlineAt&&Date.now()<exam.deadlineAt)runClock();else{const retry=$('be-submit')||$('be-next');if(!retry){app.innerHTML=top('SINAV GÖNDERİMİ','Bağlantı sorunu','Süreniz dolmuş olabilir. Cevaplarınızı kaydetmeyi tekrar deneyin.')+`<section class="be-card be-narrow"><p id="be-status">${escape(e.message)}</p><button id="be-retry-submit">Gönderimi yeniden dene</button></section>`;$('be-retry-submit').onclick=()=>submitExam(true)}}}finally{submitting=false}}
async function api(path,body){let r=await fetch('/api/books?action='+encodeURIComponent(path),{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});let j;try{j=await r.json()}catch{j={}};if(!r.ok){let e=new Error(j.error||`İşlem başarısız (${r.status})`);e.invalidLines=j.invalidLines;throw e}return j}
function top(eyebrow,title,desc){return `<section class="be-hero"><span class="v12-eyebrow">${eyebrow}</span><h1>📚 ${title}</h1><p>${desc}</p></section>`}
function status(msg=''){let x=$('be-status');if(x)x.textContent=msg}
function loading(){app.innerHTML=top('KİTAP ARKADAŞIM','Kitap Sınavları','Güvenli giriş denetleniyor…')}
async function landing(){stopExamClock();mode='student';exam=null;loading();try{let s=await api('session');if(s.student){await books();return}}catch{}login()}
function login(msg=''){stopExamClock();app.innerHTML=top('KİTAP ARKADAŞIM','Kitap Sınavları','Kitap Arkadaşım uygulamasındaki 8 karakterli mevcut kodunla giriş yap.')+`<section class="be-card be-narrow"><h2>Öğrenci Girişi</h2><form id="be-login"><label for="be-code">Öğrenci kodu</label><input id="be-code" type="password" autocomplete="off" inputmode="text" maxlength="8" pattern="[A-Za-z0-9]{8}" required placeholder="8 karakterli kod"><button class="v12-btn v12-btn-accent" type="submit">Kitapları göster →</button></form><p class="be-note" id="be-status" role="status">${escape(msg)}</p></section>`;

$('be-login').onsubmit=async e=>{e.preventDefault();let button=e.target.querySelector('button');button.disabled=true;status('Kod doğrulanıyor…');try{await api('login',{code:$('be-code').value.trim()});await books()}catch(err){status(err.message)}finally{if(button.isConnected)button.disabled=false}}}
async function books(){stopExamClock();mode='student';try{const [r,sess]=await Promise.all([api('list'),api('session')]);bookList=r.books;app.innerHTML=top('OKU · ANLA · BAŞAR','Kitap Sınavları','Sınavı aktif olan kitabını seç. Her kitabın soru sayısını yönetici belirler.')+`<section class="be-card"><div class="be-row"><h2>Aktif kitap sınavları</h2><button class="secondary" id="be-out">Güvenli çıkış</button></div><p class="be-note">Öğrenci referansınız: <strong>${escape(sess.studentRef||'—')}</strong> · Tekrar sınavı izni için yöneticiye bu referansı söyleyebilirsiniz.</p><div class="be-books">${bookList.length?bookList.map(b=>`<article class="be-book"><span class="be-book-icon">📖</span><h3>${escape(b.title)}</h3><p>${escape(b.author||'Kitap sınavı')}</p><small>${b.count} soruluk havuz · ${b.timed?`⏱️ ${formatDuration(b.timerSeconds)} süreli`:'Süresiz'}</small><button class="v12-btn v12-btn-accent" data-book="${escape(b.id)}">${Number(b.examQuestionCount)||20} soruluk sınava başla</button></article>`).join(''):'<p>Şu anda aktif kitap sınavı bulunmuyor. Yönetici soru yükleyip sınavı aktif ettiğinde burada görünecek.</p>'}</div><p id="be-status" class="be-note" role="status"></p></section>`;
$('be-out').onclick=async()=>{try{await api('logout',{type:'student'})}catch{}login('Oturum kapatıldı.')};document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>start(b.dataset.book));
}catch(e){login(e.message)}}
async function start(id){status('Sınav hazırlanıyor…');try{stopExamClock();answers=[];exam=await api('start',{bookId:id});renderExam(0);runClock()}catch(e){status(e.message)}}
let answers=[];
function renderExam(i){if(!exam)return;const qs=exam.questions;if(i===0&&answers.length!==qs.length)answers=Array(qs.length).fill(null);if(i>=qs.length){review();return}const q=qs[i];app.innerHTML=top('KİTAP SINAVI',escape(exam.book.title),`Soru ${i+1} / ${qs.length}`)+`<section class="be-card be-narrow">${timerHTML()}<div class="be-progress"><div style="width:${((i+1)/qs.length)*100}%"></div></div><span class="v12-eyebrow">${q.type==='test'?'ÇOKTAN SEÇMELİ':'KISA CEVAP'}</span><h2>${escape(q.question)}</h2><div id="be-answer">${q.type==='test'?q.options.map((opt,j)=>`<label class="be-choice"><input type="radio" name="be-choice" value="${j}" ${answers[i]===j?'checked':''}><span>${'ABCD'[j]}. ${escape(opt)}</span></label>`).join(''):`<label for="be-fill">Bir veya iki kelimelik cevabını yaz</label><input id="be-fill" maxlength="75" autocomplete="off" value="${escape(answers[i]||'')}" placeholder="Cevabım…">`}</div><div class="be-row"><button class="secondary" id="be-prev" ${i===0?'disabled':''}>← Önceki</button><button class="v12-btn v12-btn-accent" id="be-next">${i===qs.length-1?'Sınavı tamamla →':'Sonraki soru →'}</button></div><p class="be-note" id="be-status" role="status"></p></section>`;
function save(){if(q.type==='test'){let checked=document.querySelector('[name="be-choice"]:checked');answers[i]=checked?Number(checked.value):null}else answers[i]=$('be-fill').value.trim()||null}
saveCurrentAnswer=save;$('be-prev').onclick=()=>{save();renderExam(i-1)};$('be-next').onclick=()=>{save();if(answers[i]===null){status('Lütfen bu soruyu cevaplayın.');return}renderExam(i+1)}}
function review(){saveCurrentAnswer=null;app.innerHTML=top('SON KONTROL','Sınavı bitir','Yanıtlarını gönderdikten sonra değiştiremezsin.')+`<section class="be-card be-narrow">${timerHTML()}<p>${exam.questions.length} sorunun <strong>${answers.filter(a=>a!==null).length}</strong> tanesi cevaplandı.</p><div class="be-row"><button class="secondary" id="be-back">← Sorulara dön</button><button class="v12-btn v12-btn-accent" id="be-submit">Sınavı gönder →</button></div><p class="be-note" id="be-status" role="status"></p></section>`;
$('be-back').onclick=()=>renderExam(exam.questions.length-1);$('be-submit').onclick=()=>submitExam(false)}

const gameCategories={visual:'Renk ve Görsel',sound:'Ses ve Ritim',logic:'Matematik ve Mantık',ethics:'Dijital Etik',code:'Kodlama',country:'Ülkemiz',social:'Sosyal Bilgiler',brain:'Akıl-Zekâ'};
function gameAdminMarkup(){return `<section class="be-card be-results" id="be-game-admin"><h2>🎮 Oyun Yönetimi</h2><p class="be-note">Oyunları herkes için açıp kapatabilirsiniz. Değişiklikler Redis'e kaydedilir; yeniden yayımlama gerekmez.</p><div class="be-row"><label>Oyun ara <input id="be-game-search" type="search" placeholder="Oyun adı..."></label><label>Alan <select id="be-game-group"><option value="all">Tüm alanlar</option>${Object.entries(gameCategories).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Durum <select id="be-game-filter"><option value="all">Tümü</option><option value="on">Aktif</option><option value="off">Pasif</option></select></label></div><div class="be-row"><button class="secondary" id="be-game-enable-all">Seçili alanı aktif yap</button><button class="secondary" id="be-game-disable-all">Seçili alanı pasif yap</button><span id="be-game-count"></span></div><div id="be-game-status" class="be-note" role="status"></div><div class="be-table-wrap" style="max-height:510px;overflow-y:auto"><table><thead><tr><th>Oyun</th><th>Alan</th><th>Durum</th><th>İşlem</th></tr></thead><tbody id="be-games-table"><tr><td colspan="4">Oyunlar yükleniyor…</td></tr></tbody></table></div><p class="be-note">Not: Bu kontrol sitede oyunları gizler ve normal başlatmayı engeller. Herkese açık kaynak dosyalarını erişime kapatmaz.</p></section>`}
let gameAdminRows=[];
function filterGameTable(){const search=($('be-game-search')?.value||'').toLocaleLowerCase('tr-TR'),group=$('be-game-group')?.value||'all',filter=$('be-game-filter')?.value||'all';const shown=gameAdminRows.filter(g=>(group==='all'||g.category===group)&&(filter==='all'||(filter==='on'?g.active:!g.active))&&g.name.toLocaleLowerCase('tr-TR').includes(search));$('be-game-count').textContent=`${shown.length} oyun`;const body=$('be-games-table');if(!body)return;body.innerHTML=shown.map(g=>`<tr><td>${escape(g.name)}</td><td>${escape(gameCategories[g.category]||g.group)}</td><td>${g.active?'🟢 Aktif':'⚪ Pasif'}</td><td><button type="button" class="secondary" data-game-id="${escape(g.id)}">${g.active?'Pasif yap':'Aktif yap'}</button></td></tr>`).join('')||'<tr><td colspan="4">Bu filtrede oyun yok.</td></tr>';body.querySelectorAll('[data-game-id]').forEach(button=>button.onclick=async()=>{const g=gameAdminRows.find(x=>x.id===button.dataset.gameId);if(!g)return;button.disabled=true;try{await api('admin-games-set',{ids:[g.id],active:!g.active});await loadGameManagement();}catch(e){$('be-game-status').textContent=e.message;button.disabled=false}})}
async function loadGameManagement(){try{const response=await api('admin-games');gameAdminRows=response.games||[];filterGameTable();$('be-game-status').textContent='';if(typeof AIPGameControl!=='undefined')AIPGameControl.refresh(true)}catch(e){if($('be-game-status'))$('be-game-status').textContent=e.message}}
function wireGameManagement(){for(const id of ['be-game-search','be-game-group','be-game-filter'])$(id).addEventListener(id==='be-game-search'?'input':'change',filterGameTable);for(const [id,active] of [['be-game-enable-all',true],['be-game-disable-all',false]])$(id).onclick=async()=>{const group=$('be-game-group').value;const ids=gameAdminRows.filter(g=>group==='all'||g.category===group).map(g=>g.id);if(!ids.length)return;if(!confirm(`${ids.length} oyunu ${active?'aktif':'pasif'} yapmak istiyor musunuz?`))return;$(id).disabled=true;try{await api('admin-games-set',{ids,active});await loadGameManagement()}catch(e){$('be-game-status').textContent=e.message}finally{if($(id))$(id).disabled=false}};loadGameManagement()}


// V13.6 — Exam analysis, accessible only inside authenticated admin panel.
let analysisBooks=[];
const csvDownload=(filename,rows)=>{const csv='\ufeff'+rows.map(row=>row.map(cell=>'"'+String(cell??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)};
function studentNameMarkup(){return `<section class="be-card be-results" id="be-student-map"><h2>👥 Öğrenci Kimliklerini Eşleştir</h2><p class="be-note">Kitap Arkadaşım'da kime ait olduğunu bildiğiniz 8 karakterli giriş kodunu bir kez doğrulayın. Öğrencinin adını ve varsa 15 haneli numarasını girin. Kod kaydedilmez; önceki ve sonraki sonuçları otomatik isimlendirilir.</p><form id="be-student-bind" class="be-row" style="align-items:end;flex-wrap:wrap;gap:10px"><label>8 karakterli giriş kodu <input name="code" type="password" autocomplete="off" minlength="8" maxlength="8" pattern="[A-Za-z0-9]{8}" required placeholder="Öğrenci kodu"></label><label>Adı soyadı <input name="name" maxlength="90" placeholder="Örn. Öğrenci adı"></label><label>15 haneli numara (isteğe bağlı) <input name="externalId" maxlength="15" pattern="[0-9]{15}" inputmode="numeric" placeholder="15 haneli numara"></label><button type="submit" class="v12-btn v12-btn-accent">Öğrenciyi eşleştir</button></form><p class="be-note" id="be-student-map-status" role="status">Ad veya 15 haneli numaradan en az biri doldurulmalıdır. Eşleştirmeleri yalnızca yetkili yöneticiler görür.</p><div class="be-row" style="align-items:center;margin-top:16px"><h3>Eşleştirilen Öğrenciler</h3><button type="button" class="secondary" id="be-roster-refresh">Listeyi yenile</button></div><p class="be-note" id="be-roster-status" role="status">Listeyi görüntülemek için yenileyin.</p><div class="be-table-wrap" style="max-height:370px;overflow:auto"><table><thead><tr><th>Adı soyadı</th><th>15 haneli numara</th><th>Eşleştirme tarihi</th></tr></thead><tbody id="be-roster-body"></tbody></table></div></section>`}
async function loadStudentRoster(){const label=$('be-roster-status'),body=$('be-roster-body');if(!label||!body)return;label.textContent='Eşleştirmeler okunuyor…';try{const r=await api('admin-student-roster');body.innerHTML=(r.students||[]).map(v=>`<tr><td>${escape(v.name||'—')}</td><td>${escape(v.externalId||'—')}</td><td>${escape(v.updated?new Date(v.updated).toLocaleString('tr-TR'):'—')}</td></tr>`).join('')||'<tr><td colspan="3">Henüz eşleştirme bulunamadı.</td></tr>';label.textContent=`${r.total} eşleştirme görüntüleniyor.`+(r.complete?'':' Liste çok büyük olduğu için bazı kayıtlar gösterilmemiş olabilir.')}catch(e){label.textContent=e.message}}
function wireStudentMapping(){const form=$('be-student-bind');if(!form)return;const refresh=$('be-roster-refresh');if(refresh)refresh.onclick=loadStudentRoster;loadStudentRoster();form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');const msg=$('be-student-map-status');const values=new FormData(form);btn.disabled=true;msg.textContent='Kod doğrulanıyor ve eşleştiriliyor…';try{const r=await api('admin-student-bind',{code:values.get('code'),name:values.get('name'),externalId:values.get('externalId')});form.reset();await adminPanel(`Öğrenci eşleştirildi (${r.studentRef}…). Eski sınav sonuçlarına da uygulanır.`)}catch(err){msg.textContent=err.message;btn.disabled=false}};
 document.querySelectorAll('[data-student-clear]').forEach(button=>button.onclick=async()=>{if(!confirm('Öğrencinin ad ve numara eşleştirmesi kaldırılsın mı? Sınav sonuçları silinmez.'))return;button.disabled=true;try{await api('admin-student-clear',{studentId:button.dataset.studentClear});await adminPanel('Öğrenci adı eşleştirmesi kaldırıldı.')}catch(err){status(err.message);button.disabled=false}});
}
const skillNames={understanding:'Olayları anlama',characters:'Karakterleri yorumlama',causality:'Neden-sonuç kurma',inference:'Çıkarım yapma',mainidea:'Ana fikir ve kişisel yorum'};
let skillBank=null,skillPage=0,skillChanges=new Map();
function analysisMarkup(books){analysisBooks=books;return `<section class="be-card be-results" id="be-analysis-section"><h2>📈 Ayrıntılı Sınav Analizleri</h2><p class="be-note">Yalnızca yönetici görebilir. Önceki sürümlerde cevaplar saklanmadığı için soru analizi V13.6 sonrası sınavlarda başlar. Özetler son 200 sınav sonucu üzerinden hesaplanır.</p><div class="be-row"><label>Kitap seçimi <select id="be-analysis-book"><option value="">Tüm kitaplar</option>${books.map(b=>`<option value="${escape(b.id)}">${escape(b.title)}</option>`).join('')}</select></label><button type="button" class="secondary" id="be-analysis-refresh">Analizi yenile</button><button type="button" class="secondary" id="be-analysis-csv">Soru analizi CSV</button></div><div id="be-analysis-status" class="be-note" role="status">Analiz yükleniyor…</div><div id="be-analysis-content"></div><div class="be-card" style="margin-top:14px"><h3>🏷️ Soru Beceri Etiketleri</h3><p class="be-note">Her soru için ölçtüğü asıl beceriyi seçin. Yanlış beceri tahmin edilmez. Değişiklikleri kaydedince geçmiş ayrıntılı sonuçlar da rapora yansır.</p><div class="be-row"><label>Kitap <select id="be-skill-book">${books.map(b=>`<option value="${escape(b.id)}">${escape(b.title)}</option>`).join('')}</select></label><button type="button" class="secondary" id="be-skills-load">Soruları getir</button><button type="button" class="v12-btn v12-btn-accent" id="be-skills-save">Etiketleri kaydet</button></div><p class="be-note" id="be-skills-status">Henüz soru yüklenmedi.</p><div class="be-row"><label>Beceri etiketlerini TXT dosyasından içe aktar <input type="file" id="be-skills-import-file" accept=".txt,text/plain"></label><button type="button" class="secondary" id="be-skills-import">Dosyadaki etiketleri uygula</button></div><p class="be-note">Dosya soru numarası, beceri kodu ve tam soru metni içerir. Yanlış kitaba ait dosya kabul edilmez. Uyguladıktan sonra “Etiketleri kaydet” düğmesine basın.</p><div class="be-row"><label>Listedeki etiketlenmemişleri toplu etiketle <select id="be-skills-bulk"><option value="">Beceri seçin</option>${Object.entries(skillNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button type="button" class="secondary" id="be-skills-bulk-apply">Görünen etiketlenmemiş sorulara uygula</button></div><div id="be-skills-grid"></div><div class="be-row"><button class="secondary" id="be-skills-prev">← Önceki 25</button><span id="be-skills-page"></span><button class="secondary" id="be-skills-next">Sonraki 25 →</button></div></div><div class="be-card" style="margin-top:12px"><h3>Öğrencinin cevaplarını incele</h3><p class="be-note">Aşağıdaki sonuç tablosundan «Cevapları gör» seçeneğine tıklayın.</p><div id="be-detail-view"></div></div></section>`}
let currentAnalysis=null;
function renderAnalysis(r){const el=$('be-analysis-content');if(!el)return;
const types=[['TEST',r.typeStats?.test],['BOŞLUK',r.typeStats?.bosluk]];
const skillRows=Object.entries(skillNames).map(([key,name])=>{const data=r.skillStats?.[key]||{asked:0,correct:0};const ratio=data.asked?Math.round(data.correct*100/data.asked):null;return `<div style="margin:11px 0"><div class="be-row" style="justify-content:space-between"><strong>${escape(name)}</strong><span>${data.correct}/${data.asked} doğru · ${ratio===null?'Veri yok':('%'+ratio)}</span></div><div style="background:#e5e7eb;border-radius:12px;height:12px;overflow:hidden"><div style="background:#2563eb;width:${ratio??0}%;height:100%"></div></div></div>`}).join('');
const students=(r.students||[]).map((st,i)=>`<option value="${i}">${escape(st.name||st.studentId.slice(0,12)+'…')}${st.externalId?' ('+escape(st.externalId)+')':''} · ${st.tests} sınav</option>`).join('');
el.innerHTML=`<div class="be-row" style="gap:15px;flex-wrap:wrap"><strong>Seçilen sonuç: ${r.totalResults}</strong><strong>Ortalama puan: ${r.averageScore===null?'—':r.averageScore}</strong><strong>Ortalama süre: ${r.averageSeconds===null?'—':formatDuration(r.averageSeconds)}</strong><strong>Süre dolan: ${r.timedOut}</strong></div><p class="be-note">Soru bazlı kaydı olan ${r.analyzedAttempts} sınav; ayrıntısı bulunmayan eski sınav: ${r.oldResultsWithoutDetail}. Son 200 sınav sonucu incelenir; beceri başarıları yalnızca etiketli sorulardan hesaplanır.</p><div class="be-row">${types.map(([name,t])=>`<div style="padding:10px;border:1px solid #d1d5db;border-radius:9px"><strong>${name}</strong>: ${t?.answered?Math.round(t.correct/t.answered*100)+'%':'—'} <small>(${t?.correct||0}/${t?.answered||0})</small></div>`).join('')}</div><h3>📊 Okuduğunu Anlama Beceri Analizi</h3>${skillRows}<p class="be-note">Etiketsiz soru yanıtı: ${r.unclassified||0}. Bir öğrencinin yalnızca 1–2 soruda başarısız olması kesin zayıflık göstergesi değildir. Beceri raporu için en az 3 soru, daha güvenilir karşılaştırmalar için farklı sınavlar önerilir.</p><h3>👤 Öğrenci Bazında Güçlü ve Gelişime Açık Alanlar</h3><label>Öğrenci seçin <select id="be-student-analysis"><option value="">Öğrenci seçiniz</option>${students}</select></label><div id="be-student-skill-detail" class="be-note" style="margin:10px 0">Bir öğrenci seçerek beceri ve sınav gelişimini görün.</div><h3>En çok zorlanılan sorular</h3><div class="be-table-wrap" style="max-height:440px;overflow:auto"><table><thead><tr><th>Kitap</th><th>Soru</th><th>Beceri</th><th>Tür</th><th>Sorulma</th><th>Doğru</th><th>Başarı</th></tr></thead><tbody>${r.questions.map(q=>`<tr><td>${escape(analysisBooks.find(b=>b.id===q.bookId)?.title||q.bookId)}</td><td>${escape(q.question)}</td><td>${escape(skillNames[q.skill]||'Etiketsiz')}</td><td>${q.type==='test'?'Test':'Boşluk'}</td><td>${q.asked}</td><td>${q.correct}</td><td>%${q.rate}</td></tr>`).join('')||'<tr><td colspan="7">Henüz ayrıntılı soru kaydı yok.</td></tr>'}</tbody></table></div><p class="be-note">Tek kez sorulmuş sorulardaki %0 veya %100 değerleri kesin yargı için yeterli değildir.</p>`;
$('be-student-analysis').onchange=()=>renderStudentSkill(r.students?.[Number($('be-student-analysis').value)]);
}
function renderStudentSkill(st){const el=$('be-student-skill-detail');if(!el)return;if(!st){el.textContent='Öğrenci seçiniz.';return}const rows=Object.entries(skillNames).map(([k,name])=>{const data=st.skills[k],n=data?.asked||0,correct=data?.correct||0,rate=n?Math.round(correct/n*100):0;const comment=n<3?'Yetersiz veri':rate>=80?'Güçlü görünüyor':rate<60?'Ek çalışmaya ihtiyaç olabilir':'Geliştirilebilir';return `<tr><td>${escape(name)}</td><td>${correct}/${n}</td><td>${n?'%'+rate:'—'}</td><td>${comment}</td></tr>`}).join('');const timeline=(st.timeline||[]).map((t,i)=>`<tr><td>${i+1}</td><td>${escape(t.date.slice(0,16).replace('T',' '))}</td><td>${escape(analysisBooks.find(b=>b.id===t.bookId)?.title||t.bookId)}</td><td>${t.score}</td><td>${Number.isFinite(t.elapsedSeconds)?formatDuration(t.elapsedSeconds):'—'}</td></tr>`).join('');el.innerHTML=`<p><strong>${escape(st.name||st.studentId.slice(0,12)+'…')}</strong> · ${st.tests} ayrıntılı sınav</p><div class="be-table-wrap"><table><thead><tr><th>Beceri</th><th>Doğru</th><th>Başarı</th><th>Yorum</th></tr></thead><tbody>${rows}</tbody></table></div><p class="be-note">Yorumlar soru sayısına bağlı ön göstergelerdir, bireysel tanı veya kesin başarı düzeyi değildir.</p><h4>Denemeler ve gelişim</h4><div class="be-table-wrap"><table><thead><tr><th>Deneme</th><th>Tarih</th><th>Kitap</th><th>Puan</th><th>Süre</th></tr></thead><tbody>${timeline}</tbody></table></div>`}
function renderSkillBank(){const area=$('be-skills-grid');if(!area||!skillBank)return;const items=skillBank.questions,from=skillPage*25,shown=items.slice(from,from+25);const tagged=items.filter(q=>!!(skillChanges.has(q.id)?skillChanges.get(q.id):q.skill)).length;$('be-skills-status').textContent=`Toplam ${items.length} soru · ${tagged} etiketli · ${skillChanges.size} kaydedilmemiş değişiklik`;area.innerHTML=`<div class="be-table-wrap"><table><thead><tr><th>#</th><th>Soru</th><th>Beceri</th></tr></thead><tbody>${shown.map((q,i)=>`<tr><td>${from+i+1}</td><td>${escape(q.question)}</td><td><select data-skill-id="${escape(q.id)}"><option value="">Etiketsiz</option>${Object.entries(skillNames).map(([k,name])=>`<option value="${k}" ${(skillChanges.has(q.id)?skillChanges.get(q.id):q.skill)===k?'selected':''}>${name}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`;area.querySelectorAll('[data-skill-id]').forEach(node=>node.onchange=()=>{skillChanges.set(node.dataset.skillId,node.value||null);renderSkillBank()});$('be-skills-page').textContent=`${skillPage+1} / ${Math.max(1,Math.ceil(items.length/25))}`;$('be-skills-prev').disabled=skillPage===0;$('be-skills-next').disabled=from+25>=items.length}
async function loadSkillBank(){const bookId=$('be-skill-book')?.value;if(!bookId)return;$('be-skills-status').textContent='Sorular yükleniyor…';try{skillBank=await apiAdminGet('admin-skills',{bookId});skillPage=0;skillChanges.clear();renderSkillBank()}catch(e){$('be-skills-status').textContent=e.message}}
async function importSkillTagsFromFile(){
const statusEl=$('be-skills-status');
const file=$('be-skills-import-file')?.files?.[0];
if(!skillBank){statusEl.textContent='Önce kitabı seçip “Soruları getir” düğmesine basın.';return}
if(!file){statusEl.textContent='Lütfen beceri etiketi TXT dosyasını seçin.';return}
try{
 const raw=(await file.text()).replace(/^\uFEFF/,'').trim();
 const rows=raw.split(/\r?\n/).filter(x=>x.trim());
 const staged=new Map(),seen=new Set();
 const normalize=q=>String(q||'').normalize('NFC').trim().replace(/\s+/g,' ');
 if(rows.length!==skillBank.questions.length)throw Error(`Dosyada ${rows.length}, seçili kitapta ${skillBank.questions.length} soru var. Tüm sorular eşleşmediği için işlem yapılmadı.`);
 for(let i=0;i<rows.length;i++){
   const parts=rows[i].split('\t');
   if(parts.length!==3)throw Error(`${i+1}. satır 3 TAB ayrımlı alan içermiyor.`);
   const [number,skill,question]=parts;
   const index=Number(number)-1;
   if(!Number.isInteger(index)||index<0||index>=skillBank.questions.length||seen.has(index))throw Error(`${i+1}. satırdaki soru numarası geçersiz veya yinelenmiş.`);
   seen.add(index);
   if(!Object.prototype.hasOwnProperty.call(skillNames,skill))throw Error(`${i+1}. satırdaki beceri kodu tanınmadı.`);
   const bankQuestion=skillBank.questions[index];
   if(normalize(question)!==normalize(bankQuestion.question))throw Error(`${i+1}. satırdaki soru, seçili kitabın ${index+1}. sorusuyla eşleşmiyor. Hiçbir değişiklik uygulanmadı.`);
   staged.set(bankQuestion.id,skill);
 }
 const existing=skillBank.questions.filter(q=>q.skill&&staged.get(q.id)!==q.skill).length;
 if(existing&& !window.confirm(`${existing} önceden kaydedilmiş beceri etiketi değişecek. Devam edilsin mi?`))return;
 for(const [id,skill] of staged)skillChanges.set(id,skill);
 renderSkillBank();
 statusEl.textContent+=` · ${staged.size} beceri etiketi hazır. Sunucuya kaydetmek için “Etiketleri kaydet” düğmesine basın.`;
}catch(e){statusEl.textContent='İçe aktarma yapılamadı: '+e.message}
}
function wireSkills(){if(!$('be-skills-load'))return;$('be-skills-load').onclick=loadSkillBank;$('be-skills-import').onclick=importSkillTagsFromFile;$('be-skill-book').onchange=()=>{skillBank=null;skillChanges.clear();$('be-skills-grid').innerHTML='';$('be-skills-status').textContent='Yeni kitabın sorularını getirin.'};$('be-skills-prev').onclick=()=>{if(skillPage>0){skillPage--;renderSkillBank()}};$('be-skills-next').onclick=()=>{if(skillBank&&(skillPage+1)*25<skillBank.questions.length){skillPage++;renderSkillBank()}};$('be-skills-bulk-apply').onclick=()=>{if(!skillBank)return;const v=$('be-skills-bulk').value;if(!skillNames[v])return;for(const q of skillBank.questions.slice(skillPage*25,skillPage*25+25))if(!(skillChanges.has(q.id)?skillChanges.get(q.id):q.skill))skillChanges.set(q.id,v);renderSkillBank()};$('be-skills-save').onclick=async()=>{if(!skillBank||!skillChanges.size)return;const btn=$('be-skills-save');btn.disabled=true;try{const changes=[...skillChanges].map(([id,skill])=>({id,skill}));for(let i=0;i<changes.length;i+=250)await api('admin-skills-set',{bookId:skillBank.bookId,changes:changes.slice(i,i+250)});await loadSkillBank();await loadAnalysis();$('be-skills-status').textContent+=' · Kaydedildi.'}catch(e){$('be-skills-status').textContent=e.message}finally{btn.disabled=false}};loadSkillBank()}
async function apiAdminGet(action,params={}){const u=new URL('/api/books',location.origin);u.searchParams.set('action',action);for(const [k,v] of Object.entries(params))if(v)u.searchParams.set(k,v);const r=await fetch(u,{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Analiz alınamadı.');return d}
async function loadAnalysis(){const el=$('be-analysis-status');if(!el)return;el.textContent='Analiz hesaplanıyor…';try{const bookId=$('be-analysis-book').value;const selected=$('be-student-analysis')?.value||'';const response=await apiAdminGet('admin-analysis',{bookId});currentAnalysis=response;renderAnalysis(response);if(selected&&$('be-student-analysis')){$('be-student-analysis').value=selected;$('be-student-analysis').dispatchEvent(new Event('change'))}el.textContent=`Son ${response.totalResults} sınav sonucu incelendi.`}catch(e){el.textContent=e.message}}
function formatMarkedAnswer(q,value){if(q.type==='test'){if(!Number.isInteger(value)||value<0||value>3)return 'Boş bırakılmış';return 'ABCD'[value]+') '+(q.options?.[value]||'')}return String(value??'').trim()||'Boş bırakılmış'}
async function showExamDetail(id){const area=$('be-detail-view');if(!area)return;area.textContent='Öğrencinin cevapları yükleniyor…';try{const d=await apiAdminGet('admin-detail',{id});area.innerHTML=`<p><strong>${escape(d.result.created.slice(0,16).replace('T',' '))}</strong> · ${d.result.correct}/${d.result.total} doğru · ${d.result.score} puan · ${Number.isFinite(d.result.elapsedSeconds)?formatDuration(d.result.elapsedSeconds):'—'}</p>${d.questions.map((q,i)=>`<div style="padding:12px 0;border-bottom:1px solid #e5e7eb"><strong>${i+1}. ${escape(q.question)}</strong> <span style="font-weight:700;color:${q.correct?'#15803d':'#b91c1c'}">${q.correct?'✓ Doğru':'✗ Yanlış'}</span><div>Öğrenci: ${escape(formatMarkedAnswer(q,q.studentAnswer))}</div><div>Doğru cevap: ${escape(formatMarkedAnswer(q,q.type==='test'?q.correctAnswer:null))}${q.type==='bosluk'?escape((q.correctAnswer||[]).join(' / ')):''}</div></div>`).join('')}`;area.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){area.textContent=e.message}}
function wireAnalysis(){if(!$('be-analysis-section'))return;$('be-analysis-book').onchange=loadAnalysis;$('be-analysis-refresh').onclick=loadAnalysis;$('be-analysis-csv').onclick=()=>{if(!currentAnalysis)return;csvDownload('kitap-soru-analizi.csv',[['Kitap','Soru','Tür','Sorulma','Doğru','Başarı %'],...currentAnalysis.questions.map(q=>[analysisBooks.find(b=>b.id===q.bookId)?.title||q.bookId,q.question,q.type,q.asked,q.correct,q.rate])])};document.querySelectorAll('[data-answer-detail]').forEach(button=>button.onclick=()=>showExamDetail(button.dataset.answerDetail));wireSkills();loadAnalysis()}


// V13.9: Yöneticiye özel öğrenci portfolyosu. Sonuçlar ve anahtarlar yalnızca yetkili API'den alınır.
let portfolioResults=[],portfolioBooks=[],portfolioLabels={};
function portfolioMarkup(){return `<section class="be-card be-results" id="be-student-portfolio"><h2>📁 Öğrenci Sınav Dosyası</h2><p class="be-note">Bir öğrenciyi seçerek son 200 sınav kaydı içindeki kitap sınavlarını ve ayrıntılı yanıtlarını inceleyin. Kırmızı yanlış, yeşil doğru, gri boş yanıt anlamına gelir. Eski sürümlerde soru bazlı detay bulunmayabilir.</p><div class="be-row" style="gap:12px;align-items:end;flex-wrap:wrap"><label>Öğrenci ara <input type="search" id="be-portfolio-search" placeholder="Ad, öğrenci numarası veya referans"></label><label>Öğrenci seçin <select id="be-portfolio-student"><option value="">Öğrenci seçiniz</option></select></label><button type="button" class="secondary" id="be-portfolio-refresh">Sonuçları yenile</button></div><p id="be-portfolio-status" class="be-note" role="status"></p><div id="be-portfolio-summary"></div><div id="be-portfolio-attempts"></div><div id="be-portfolio-detail"></div></section>`}
function portfolioStudents(){const map=new Map();for(const r of portfolioResults){if(!r.studentId)continue;const label=portfolioLabels[r.studentId]||{};if(!map.has(r.studentId))map.set(r.studentId,{studentId:r.studentId,name:label.name||'',externalId:label.externalId||'',count:0});map.get(r.studentId).count++}return [...map.values()].sort((a,b)=>(a.name||a.externalId||a.studentId).localeCompare(b.name||b.externalId||b.studentId,'tr'))}
function portfolioStudentLabel(st){return [st.name||st.studentId.slice(0,12)+'…',st.externalId?'No: '+st.externalId:'',`${st.count} sınav`].filter(Boolean).join(' · ')}
function filterPortfolioStudents(){const select=$('be-portfolio-student');if(!select)return;const old=select.value;const query=($('be-portfolio-search')?.value||'').trim().toLocaleLowerCase('tr-TR');const list=portfolioStudents().filter(s=>!query||[s.name,s.externalId,s.studentId].some(v=>v.toLocaleLowerCase('tr-TR').includes(query)));select.innerHTML='<option value="">Öğrenci seçiniz</option>'+list.map(s=>`<option value="${escape(s.studentId)}">${escape(portfolioStudentLabel(s))}</option>`).join('');if(list.some(s=>s.studentId===old))select.value=old;else{select.value='';$('be-portfolio-summary').innerHTML='';$('be-portfolio-attempts').innerHTML='';$('be-portfolio-detail').innerHTML=''}}
function portfolioRenderStudent(){const id=$('be-portfolio-student')?.value;if(!id)return;const records=portfolioResults.filter(r=>r.studentId===id).sort((a,b)=>b.created.localeCompare(a.created));const label=portfolioLabels[id]||{};const durations=records.map(r=>r.elapsedSeconds).filter(Number.isFinite);const avg=records.length?Math.round(records.reduce((a,b)=>a+(Number(b.score)||0),0)/records.length):null;const times=durations.length?Math.round(durations.reduce((a,b)=>a+b,0)/durations.length):null;const titles=new Set(records.map(r=>r.bookId));const summary=$('be-portfolio-summary');summary.innerHTML=`<h3>${escape(label.name||id.slice(0,12)+'…')} ${label.externalId?`<small>(${escape(label.externalId)})</small>`:''}</h3><div class="be-row" style="gap:14px;flex-wrap:wrap"><strong>${records.length} sınav kaydı</strong><strong>${titles.size} farklı kitap</strong><strong>Ortalama puan: ${avg??'—'}</strong><strong>Ortalama süre: ${times===null?'—':formatDuration(times)}</strong></div><p class="be-note">Aynı kitabın birden fazla denemesi ayrı ayrı listelenir. Bu liste yalnızca sunucunun döndürdüğü son 200 sınav kaydını kapsar.</p>`;
 const grouped=new Map();for(const r of records){if(!grouped.has(r.bookId))grouped.set(r.bookId,[]);grouped.get(r.bookId).push(r)}
 $('be-portfolio-attempts').innerHTML=[...grouped].map(([bookId,items])=>`<div style="margin:18px 0"><h4>📖 ${escape(portfolioBooks.find(b=>b.id===bookId)?.title||bookId)} (${items.length} deneme)</h4><div class="be-table-wrap"><table><thead><tr><th>Tarih</th><th>Doğru</th><th>Puan</th><th>Süre</th><th>İncele</th></tr></thead><tbody>${items.map((r,i)=>`<tr><td>${escape(new Date(r.created).toLocaleString('tr-TR'))}</td><td>${r.correct}/${r.total}</td><td>${r.score}</td><td>${Number.isFinite(r.elapsedSeconds)?formatDuration(r.elapsedSeconds):'—'}</td><td><button type="button" class="secondary" data-portfolio-result="${escape(r.id)}">Cevapları ve becerileri gör</button></td></tr>`).join('')}</tbody></table></div></div>`).join('');$('be-portfolio-detail').innerHTML='';summary.insertAdjacentHTML('beforeend','<div id="be-portfolio-longitudinal" class="be-note">Bütün sınavların beceri özeti hesaplanıyor…</div>');loadPortfolioSkills(id);document.querySelectorAll('[data-portfolio-result]').forEach(btn=>btn.onclick=()=>portfolioDetail(btn.dataset.portfolioResult));}
async function loadPortfolioSkills(id){const el=$('be-portfolio-longitudinal');if(!el)return;try{const result=await apiAdminGet('admin-analysis',{studentId:id});if($('be-portfolio-student')?.value!==id)return;const student=(result.students||[]).find(v=>v.studentId===id);if(!student){el.textContent='Bu öğrencinin analiz edilebilir ayrıntılı sınav kaydı bulunmuyor.';return}const rows=Object.entries(skillNames).map(([key,name])=>{const stat=student.skills?.[key]||{},asked=stat.asked||0,correct=stat.correct||0,percent=asked?Math.round(correct/asked*100):null;const advice=asked<3?'Yetersiz veri':percent>=80?'Güçlü görünüyor':percent<60?'Desteklenebilir':'Geliştirilebilir';return `<tr><td>${escape(name)}</td><td>${correct}/${asked}</td><td>${percent===null?'—':'%'+percent}</td><td>${advice}</td></tr>`}).join('');el.innerHTML=`<h4>📊 Öğrencinin bütün ayrıntılı sınavlarındaki beceri profili</h4><p>${student.tests} ayrıntılı sınav analiz edildi. ${result.oldResultsWithoutDetail} eski sınavın soru ayrıntıları bulunmuyor.</p><div class="be-table-wrap"><table><thead><tr><th>Beceri</th><th>Doğru / Sorulan</th><th>Başarı</th><th>Ön yorum</th></tr></thead><tbody>${rows}</tbody></table></div><p class="be-note">Beceriler farklı kitap ve denemelerdeki etiketlenmiş sorular üzerinden hesaplanır. Bu rapor kesin tanı değildir.</p>`}catch(e){if($('be-portfolio-student')?.value===id)el.textContent='Beceri profili okunamadı: '+e.message}}
async function portfolioDetail(id){const area=$('be-portfolio-detail');if(!area)return;area.textContent='Sınav cevapları ve beceri etiketleri yükleniyor…';try{const d=await apiAdminGet('admin-detail',{id});const book=portfolioBooks.find(b=>b.id===d.result.bookId);let currentBank=null;try{currentBank=await apiAdminGet('admin-skills',{bookId:d.result.bookId})}catch{}const skillMap=new Map((currentBank?.questions||[]).map(q=>[q.id,q.skill]));const skills=Object.fromEntries(Object.keys(skillNames).map(k=>[k,{asked:0,correct:0}]));let untagged=0,wrong=0,blank=0;const isBlank=q=>q.studentAnswer==null||String(q.studentAnswer).trim()==='';const questionHtml=d.questions.map((q,i)=>{const empty=isBlank(q);const state=empty?'Boş':q.correct?'Doğru':'Yanlış';if(empty)blank++;else if(!q.correct)wrong++;const skill=skillMap.get(q.questionId)||q.skill;if(skill&&skills[skill]){skills[skill].asked++;if(q.correct)skills[skill].correct++}else untagged++;const color=empty?'#6b7280':q.correct?'#15803d':'#b91c1c';const background=empty?'#f3f4f6':q.correct?'#f0fdf4':'#fef2f2';return `<div style="padding:12px;margin:9px 0;border:1px solid ${color};background:${background};border-radius:10px"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><strong>${i+1}. ${escape(q.question)}</strong><span style="font-weight:800;color:${color}">${state==='Doğru'?'✓':state==='Yanlış'?'✗':'○'} ${state}</span></div><small>${escape(skillNames[skill]||'Etiketsiz')} · ${q.type==='test'?'Test':'Boşluk doldurma'}</small><div style="margin-top:7px;color:${color}"><strong>Öğrencinin cevabı:</strong> ${escape(formatMarkedAnswer(q,q.studentAnswer))}</div><div><strong>Doğru cevap:</strong> ${q.type==='test'?escape(formatMarkedAnswer(q,q.correctAnswer)):escape((q.correctAnswer||[]).join(' / '))}</div></div>`}).join('');const skillHtml=Object.entries(skills).map(([key,val])=>{const percent=val.asked?Math.round(100*val.correct/val.asked):null;const note=val.asked===0?'Bu sınavda ölçülmedi':val.asked<3?'Yorum için az soru':percent>=80?'Başarılı görünüm':percent<60?'Geliştirilebilir':'Orta düzey';return `<tr><td>${escape(skillNames[key])}</td><td>${val.correct}/${val.asked}</td><td>${percent===null?'—':'%'+percent}</td><td>${note}</td></tr>`}).join('');area.innerHTML=`<div class="be-card" style="margin:14px 0"><h3>📝 ${escape(book?.title||'Kitap sınavı')} — Sınav Ayrıntısı</h3><div class="be-row" style="flex-wrap:wrap;gap:12px"><strong>${d.result.correct}/${d.result.total} doğru</strong><strong>${wrong} yanlış</strong><strong>${blank} boş</strong><strong>${d.result.score} puan</strong><strong>${Number.isFinite(d.result.elapsedSeconds)?formatDuration(d.result.elapsedSeconds):'—'}</strong></div><h4>Bu sınavın beceri özeti</h4><div class="be-table-wrap"><table><thead><tr><th>Beceri</th><th>Doğru</th><th>Başarı</th><th>Yorum</th></tr></thead><tbody>${skillHtml}</tbody></table></div><p class="be-note">${untagged} soru etiketsiz. Bir sınavdaki az sayıda soru tek başına kalıcı güçlü/zayıf beceri anlamına gelmez. Daha güvenilir sonuç için farklı sınavları birlikte inceleyin.</p><h4>Renkli soru ve cevap dökümü</h4>${questionHtml}</div>`;area.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){area.textContent='Ayrıntılar görüntülenemedi: '+e.message}}
function wireStudentPortfolio(result,books){if(!$('be-student-portfolio'))return;portfolioResults=result.results||[];portfolioLabels=result.studentLabels||{};portfolioBooks=books;$('be-portfolio-search').oninput=filterPortfolioStudents;$('be-portfolio-student').onchange=portfolioRenderStudent;$('be-portfolio-refresh').onclick=async()=>{const note=$('be-portfolio-status');note.textContent='Öğrenci sonuçları yenileniyor…';try{const updated=await api('admin-results');portfolioResults=updated.results||[];portfolioLabels=updated.studentLabels||{};filterPortfolioStudents();note.textContent=`Son ${portfolioResults.length} sınav sonucu yenilendi.`}catch(e){note.textContent=e.message}};filterPortfolioStudents();$('be-portfolio-status').textContent=`${portfolioStudents().length} öğrenci, ${portfolioResults.length} sınav kaydı. Önce öğrenciyi seçin.`}

function adminEntry(msg=''){stopExamClock();mode='admin';app.innerHTML=top('YÖNETİCİYE ÖZEL','Kitap Sınavları Yönetimi','Kitap oluşturma, soru yükleme ve sınavları açıp kapatma.')+`<section class="be-card be-narrow"><h2>Yönetici Girişi</h2><form id="be-admin-form"><label>Yönetici parolası</label><input id="be-admin-password" type="password" autocomplete="off" required><button class="v12-btn v12-btn-accent" type="submit">Yönetim panelini aç</button></form><p class="be-note" id="be-status" role="status">${escape(msg)}</p><button class="secondary" id="be-return">← Öğrenci girişine dön</button></section>`;
$('be-return').onclick=login;$('be-admin-form').onsubmit=async e=>{e.preventDefault();let btn=e.target.querySelector('button');btn.disabled=true;status('Giriş kontrol ediliyor…');try{await api('admin-login',{password:$('be-admin-password').value});await adminPanel()}catch(err){status(err.message)}finally{if(btn.isConnected)btn.disabled=false}}}
async function adminPanel(msg=''){mode='admin';try{let [list,result]=await Promise.all([api('list'),api('admin-results')]);const books=list.books;app.innerHTML=top('YÖNETİCİ PANELİ','Kitap Sınavları','Kitapları, soru havuzlarını ve öğrenci sonuçlarını yönetin.')+`<div class="be-admin-grid"><section class="be-card"><div class="be-row"><h2>Kitaplar</h2><button class="secondary" id="be-admin-out">Çıkış</button></div><div id="be-books-admin">${books.map(b=>`<div class="be-admin-book"><div><strong>${escape(b.title)}</strong><small>${b.count} soru · ${b.active?'AKTİF':'PASİF'}</small></div><button class="secondary" data-toggle="${escape(b.id)}" data-active="${b.active?'false':'true'}">${b.active?'Pasif yap':'Aktif yap'}</button></div><form class="be-book-count" data-count-book="${escape(b.id)}" style="display:flex;flex-wrap:wrap;align-items:end;gap:8px;margin:8px 0 8px;padding:9px;border:1px solid #d1d5db;border-radius:10px"><label>Sınavdaki soru sayısı <select name="questionCount">${Array.from({length:26},(_,i)=>i+5).map(n=>`<option value="${n}" ${n===(Number(b.examQuestionCount)||20)?'selected':''}>${n} soru</option>`).join('')}</select></label><button class="secondary" type="submit">Soru sayısını kaydet</button></form><form class="be-book-timer" data-timer-book="${escape(b.id)}" style="display:flex;flex-wrap:wrap;align-items:end;gap:8px;margin:8px 0 15px;padding:9px;border:1px solid #d1d5db;border-radius:10px"><label style="display:flex;align-items:center;gap:5px"><input type="checkbox" name="timed" ${b.timed?'checked':''}> Süreli sınav</label><label>Dakika <select name="minutes">${Array.from({length:60},(_,n)=>`<option value="${n}" ${Math.floor((b.timerSeconds||0)/60)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Saniye <select name="seconds">${Array.from({length:60},(_,n)=>`<option value="${n}" ${(b.timerSeconds||0)%60===n?'selected':''}>${String(n).padStart(2,'0')}</option>`).join('')}</select></label><button class="secondary" type="submit">Süreyi kaydet</button></form>`).join('')||'<p>Henüz kitap eklenmedi.</p>'}</div><h3>Yeni kitap sınavı</h3><form id="be-create"><label>Kitap/sınav adı<input name="title" maxlength="130" required></label><label>Yazar (isteğe bağlı)<input name="author" maxlength="100"></label><label>Sınıf düzeyi<select name="grade">${[0,1,2,3,4].map(i=>`<option value="${i}">${i===0?'Ana sınıfı':i+'. sınıf'}</option>`).join('')}</select></label><button class="v12-btn v12-btn-accent" type="submit">Kitap oluştur</button></form></section><section class="be-card"><h2>Toplu soru yükleme</h2><p>Bir kitap seçin. Yükleme sırasında hatalı satır varsa hiçbir soru eklenmez.</p><form id="be-import"><label>Kitap<select name="bookId" required>${books.map(b=>`<option value="${escape(b.id)}">${escape(b.title)}</option>`).join('')}</select></label><label>Sorular<textarea name="text" rows="11" placeholder="TEST - Soru? - A seçeneği - B seçeneği - C seçeneği - D seçeneği - A\nBOSLUK - Kısa cevaplı soru? - kabul edilen cevap / alternatif"></textarea></label><label class="be-check"><input type="checkbox" name="replace"> Bu kitabın eski sorularını tamamen değiştir</label><button class="v12-btn v12-btn-accent" type="submit" ${books.length?'':'disabled'}>Soruları yükle</button></form><p class="be-note">Sınavı aktif etmek için en az 100 geçerli soru gerekir. Yanıtları öğrencilerin tarayıcısına gönderilmez.</p></section></div>${gameAdminMarkup()}${studentNameMarkup()}${portfolioMarkup()}${analysisMarkup(books)}<section class="be-card be-results"><h2>📊 Son 7 Gün Kullanım İstatistikleri</h2><p class="be-note">Anonim toplamlar. Giriş sayıları sayfa/oyun açılışlarını; süreler yalnızca açık ve yakın zamanda etkileşimde bulunulan sekmeleri gösterir. Süreler yaklaşık değerlerdir. Geçmiş dönem verileri geriye dönük oluşmaz.</p><div class="be-table-wrap"><table><thead><tr><th>Sayfa / Oyun</th><th>Açılış</th><th>Yaklaşık aktif süre</th></tr></thead><tbody>${(result.usage?.items||[]).map(row=>`<tr><td>${escape(row.name)}</td><td>${row.views}</td><td>${Math.round(row.seconds/60)} dk</td></tr>`).join('')||'<tr><td colspan="3">Henüz kullanım verisi yok. Bu güncelleme yayımlandıktan sonra toplanmaya başlar.</td></tr>'}</tbody></table></div><div class="be-row"><small>Son 7 gün toplam: ${(result.usage?.days||[]).reduce((n,d)=>n+d.views,0)} açılış</small></div></section><section class="be-card be-results"><h2>Son 200 sınav sonucu</h2><div class="be-row"><span>Eşleştirilen öğrencilerin ad ve numaraları görüntülenir. Eşleştirilmemiş öğrencilerde güvenli referans gösterilir. Tekrar hakkı yalnızca ilgili kitap ve öğrenci için geçerlidir.</span><button class="secondary" id="be-export">Sonuçlar CSV</button><button class="secondary" id="be-backup">Soru bankası yedeği</button></div><div class="be-table-wrap"><table><thead><tr><th>Tarih</th><th>Kitap</th><th>Öğrenci / Kimlik</th><th>Doğru</th><th>Puan</th><th>Tamamlama süresi</th><th>Durum</th><th>Cevaplar</th><th>Tekrar izni</th></tr></thead><tbody>${result.results.map(r=>`<tr><td>${escape(r.created.slice(0,16).replace('T',' '))}</td><td>${escape((books.find(b=>b.id===r.bookId)||{}).title||r.bookId)}</td><td>${result.studentLabels?.[r.studentId]?.name?`<strong>${escape(result.studentLabels[r.studentId].name)}</strong><br>`:''}${result.studentLabels?.[r.studentId]?.externalId?`<small>No: ${escape(result.studentLabels[r.studentId].externalId)}</small><br>`:''}<small>${escape(r.studentId.slice(0,12))}…</small>${result.studentLabels?.[r.studentId]?`<br><button type="button" class="secondary" data-student-clear="${escape(r.studentId)}">Eşleştirmeyi kaldır</button>`:''}</td><td>${r.correct}/${r.total}</td><td>${r.score}</td><td>${Number.isFinite(r.elapsedSeconds)?formatDuration(r.elapsedSeconds):'—'}</td><td>${r.timedOut?'Süre doldu':(r.elapsedSeconds===undefined?'Eski kayıt':'Tamamlandı')}</td><td><button type="button" class="secondary" data-answer-detail="${escape(r.id)}">Cevapları gör</button></td><td><button type="button" class="secondary" data-retake="${escape(r.bookId)}" data-student="${escape(r.studentId)}" data-allow="true">Tekrar hakkı ver</button><button type="button" class="secondary" data-retake="${escape(r.bookId)}" data-student="${escape(r.studentId)}" data-allow="false">İzni kaldır</button></td></tr>`).join('')||'<tr><td colspan="9">Henüz tamamlanan sınav yok.</td></tr>'}</tbody></table></div></section><p id="be-status" class="be-note" role="status">${escape(msg)}</p>`;
wireGameManagement();wireAnalysis();wireStudentMapping();wireStudentPortfolio(result,books);
document.querySelectorAll('[data-count-book]').forEach(form=>{form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{await api('admin-question-count',{bookId:form.dataset.countBook,count:Number(form.elements.questionCount.value)});await adminPanel('Kitabın soru sayısı kaydedildi. Yeni başlayan sınavlarda geçerli olacaktır.')}catch(err){status(err.message);btn.disabled=false}}});
document.querySelectorAll('[data-timer-book]').forEach(form=>{const check=form.elements.timed;const minutes=form.elements.minutes,seconds=form.elements.seconds;const sync=()=>{minutes.disabled=!check.checked;seconds.disabled=!check.checked};check.onchange=sync;sync();form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{await api('admin-timer',{bookId:form.dataset.timerBook,timed:check.checked,minutes:Number(minutes.value),seconds:Number(seconds.value)});await adminPanel('Kitabın süre ayarı kaydedildi. Yeni başlayan sınavlarda geçerli olacaktır.')}catch(err){status(err.message);btn.disabled=false}}});
document.querySelectorAll('[data-retake]').forEach(b=>b.onclick=async()=>{const allow=b.dataset.allow==='true';if(!confirm(allow?'Bu öğrenciye yalnızca seçilen kitap için BİR yeni sınav hakkı verilsin mi?':'Bu öğrenci için kullanılmamış tekrar sınav izni kaldırılsın mı?'))return;b.disabled=true;try{await api('admin-retake',{bookId:b.dataset.retake,studentId:b.dataset.student,allow});await adminPanel(allow?'Tekrar sınavı için tek kullanımlık izin verildi.':'Tekrar sınavı izni kaldırıldı.')}catch(e){status(e.message);b.disabled=false}});
$('be-admin-out').onclick=async()=>{await api('logout',{type:'admin'});adminEntry()};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('admin-toggle',{bookId:b.dataset.toggle,active:b.dataset.active==='true'});await adminPanel('Sınav durumu güncellendi.')}catch(e){status(e.message);b.disabled=false}});
$('be-create').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target);try{await api('admin-create',{title:fd.get('title'),author:fd.get('author'),grade:fd.get('grade')});await adminPanel('Yeni kitap oluşturuldu. Soruları yükleyebilirsiniz.')}catch(err){status(err.message)}};
$('be-import').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target);if(fd.get('replace')&&!confirm('Bu kitaptaki mevcut soru havuzunun TAMAMI silinip yeni sorularla değiştirilecek. Onaylıyor musunuz?'))return;status('Sorular yükleniyor…');try{let r=await api('admin-import',{bookId:fd.get('bookId'),text:fd.get('text'),replace:!!fd.get('replace')});await adminPanel(`${r.imported} soru yüklendi. Toplam ${r.count} soru.`)}catch(err){status(err.message+(err.invalidLines?' Hatalı satırlar: '+err.invalidLines.join(', '):''))}};
$('be-backup').onclick=async()=>{try{let r=await api('admin-backup');let blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kitap-sinavlari-yedek.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}catch(e){status(e.message)}};
$('be-export').onclick=()=>{let rows=[['Tarih','Kitap','Öğrenci adı','15 haneli numara','Öğrenci takma kimliği','Doğru','Toplam','Puan','Tamamlama süresi (saniye)','Süre doldu mu'],...result.results.map(r=>[r.created,(books.find(b=>b.id===r.bookId)||{}).title||r.bookId,result.studentLabels?.[r.studentId]?.name||'',result.studentLabels?.[r.studentId]?.externalId||'',r.studentId,r.correct,r.total,r.score,r.elapsedSeconds??'',r.timedOut?'Evet':'Hayır'])];let csv='\ufeff'+rows.map(a=>a.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\r\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kitap-sinav-sonuclari.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
}catch(e){adminEntry(e.message)}}
return {landing,adminEntry};
})();
